@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Manrope:wght@400;500;600;700&display=swap');

:root { font-family: 'DM Sans', sans-serif; color:#262720; background:#f8f7f3; font-synthesis:none; }
* { box-sizing:border-box; }
body { margin:0; min-width:320px; min-height:100vh; }
button,input,textarea,select { font:inherit; }
button { cursor:pointer; }
.app { min-height:100vh; display:grid; grid-template-columns:244px 1fr; }
.sidebar { position:fixed; inset:0 auto 0 0; width:244px; padding:30px 18px 20px; background:#eeeee8; border-right:1px solid #deded6; display:flex; flex-direction:column; z-index:10; }
.brand { display:flex; align-items:center; gap:10px; padding:0 10px 28px; font:700 21px 'Manrope'; letter-spacing:-.5px; }
.brand-mark { width:31px; height:31px; border-radius:9px; display:grid; place-items:center; color:#fff; background:#6f725f; box-shadow:0 3px 8px #6f725f38; }
nav { display:flex; flex-direction:column; gap:4px; }
.nav-item { width:100%; border:0; background:transparent; height:40px; border-radius:8px; display:flex; align-items:center; gap:11px; padding:0 11px; color:#67685f; text-align:left; font-size:14px; }
.nav-item span { flex:1; }.nav-item em { font-style:normal; color:#929389; font-size:12px; }
.nav-item:hover { background:#e7e7e0; color:#33342e; }.nav-item.active { background:#dedfd5; color:#383b30; font-weight:600; }.nav-item.active svg { color:#686b58; }
.nav-label { margin:30px 10px 8px; display:flex; justify-content:space-between; align-items:center; color:#98998f; font-size:10px; font-weight:700; letter-spacing:1.2px; }
.nav-label button { border:0;background:none;color:#8d8f83;padding:3px;display:grid;place-items:center; }
.collections .nav-item svg { fill:currentColor; stroke-width:0; width:14px; }
.sidebar-foot { margin-top:auto; }.storage { padding:14px 10px 18px; border-bottom:1px solid #dbdbd3; }.storage div:first-child { display:flex;justify-content:space-between;font-size:12px;font-weight:600; }.bar { height:4px;background:#d5d5cc;border-radius:5px;margin:9px 0 7px;overflow:hidden; }.bar i { display:block;width:42%;height:100%;background:#7a7d68;border-radius:5px; }.storage small { color:#999a91;font-size:11px; }
.settings { background:none;border:0;color:#6f7069;display:flex;align-items:center;gap:10px;padding:18px 10px;width:100%;font-size:13px; }
.profile { display:flex;align-items:center;gap:10px;padding:13px 8px 0; }.avatar { width:34px;height:34px;border-radius:50%;background:#d2c1a5;color:#5d503c;display:grid;place-items:center;font-size:11px;font-weight:700; }.profile>div:nth-child(2){display:flex;flex-direction:column;min-width:0;flex:1}.profile strong{font-size:12px}.profile span{font-size:10px;color:#99998f;margin-top:2px}.profile svg{color:#99998f}
main { grid-column:2; min-width:0; }
header { height:80px;border-bottom:1px solid #e5e3dd;padding:0 42px;display:flex;align-items:center;justify-content:space-between;background:#f8f7f3d9;backdrop-filter:blur(12px);position:sticky;top:0;z-index:5; }
.search { display:flex;align-items:center;gap:11px;color:#97988f;width:min(460px,50vw); }.search input { border:0;outline:0;background:transparent;width:100%;color:#2c2d27;font-size:14px; }.search input::placeholder{color:#aaa9a2}.search kbd{border:1px solid #dad9d2;background:#f2f1ec;border-radius:5px;padding:3px 7px;font:11px 'DM Sans';white-space:nowrap;color:#99998f}
.add { border:0;background:#6f725f;color:white;padding:10px 15px;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:8px;font-weight:600;font-size:13px;box-shadow:0 2px 5px #4f524329;transition:.18s; }.add:hover{background:#5f6250;transform:translateY(-1px)}
.mobile-brand{display:none}.content { padding:48px 42px 70px; max-width:1440px; margin:0 auto; }
.page-head { display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:34px; }.eyebrow{color:#8a8c7b!important;font-size:10px!important;font-weight:700;letter-spacing:1.5px;margin-bottom:8px!important}.page-head h1 { font:600 30px 'Manrope';letter-spacing:-1px;margin:0 0 7px; }.page-head p { margin:0;color:#93938b;font-size:13px; }
.controls { display:flex;gap:10px; }.sort { border:1px solid #deddd6;background:#f8f7f3;color:#6f7068;border-radius:8px;padding:8px 11px;display:flex;gap:12px;align-items:center;font-size:12px; }.view-toggle { display:flex;border:1px solid #deddd6;border-radius:8px;padding:3px; }.view-toggle button{border:0;background:transparent;color:#9a9a91;width:32px;border-radius:5px;display:grid;place-items:center}.view-toggle button.active{background:#e7e6df;color:#4e5045}
