import { chromium } from '@playwright/test';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1000}});
const errors=[];
page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
page.on('pageerror',e=>errors.push(String(e)));
await page.goto('http://127.0.0.1:4000',{waitUntil:'networkidle'});
await page.evaluate(()=>localStorage.clear()); await page.reload({waitUntil:'networkidle'});
const initial=await page.locator('.card').count();
// Live metadata and save
await page.getByRole('button',{name:'Add bookmark'}).first().click();
await page.getByLabel('URL').fill('https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout');
await page.getByText('Page details added automatically').waitFor({timeout:12000});
await page.getByRole('button',{name:'Save to Stash'}).click();
await page.getByText('Bookmark saved').waitFor();
if(await page.locator('.card').count()!==initial+1) throw new Error('save count');
// Favorite and favorites filter
await page.locator('.card').first().getByRole('button',{name:'Favorite'}).click();
await page.getByRole('button',{name:/Favorites/}).click();
if(await page.locator('.card').count()<1) throw new Error('favorite filter');
// Create a collection
await page.getByRole('button',{name:'Add collection'}).click();
await page.getByLabel('Collection name').fill('Research');
await page.getByLabel('Collection name').press('Enter');
await page.getByRole('button',{name:/All bookmarks/}).click();
// keyboard search
await page.keyboard.press('Control+k');
if(!(await page.getByLabel('Search bookmarks').evaluate(el=>el===document.activeElement))) throw new Error('shortcut focus');
await page.getByLabel('Search bookmarks').fill('CSS grid');
if(await page.locator('.card').count()!==1) throw new Error('search');
await page.getByLabel('Search bookmarks').fill('');
// View toggle
await page.getByRole('button',{name:'List view'}).click();
if(!(await page.locator('.bookmarks').evaluate(el=>el.classList.contains('list')))) throw new Error('list view');
// Export
const downloadPromise=page.waitForEvent('download');
await page.getByRole('button',{name:/Export library/}).click();
const download=await downloadPromise;
if(await download.suggestedFilename()!=='stash-bookmarks.json') throw new Error('export filename');
// Responsive add dialog stays reachable
await page.setViewportSize({width:390,height:700});
await page.getByRole('button',{name:'Add bookmark'}).first().click();
const box=await page.locator('.modal').boundingBox();
if(!box || box.width>390) throw new Error('mobile modal');
console.log(JSON.stringify({metadata_save:'ok',favorite_filter:'ok',collection_create:'ok',search_shortcut:'ok',list_view:'ok',export:'ok',mobile_modal:'ok',console_errors:errors}));
await browser.close();
